using System;
using System.IO;
using System.Text.Json;
using Xunit;

namespace LegacyTradeReconciliation.CharacterizationTests;

public class CharacterizationTests
{
    [Fact]
    public void BaselineGoldenMasterFixtureMatchesExpected()
    {
        var fixtureRoot = GetFixtureRoot("baseline");
        var outputDirectory = PrepareOutputDirectory("baseline");

        ExecuteBatch(fixtureRoot, outputDirectory);

        AssertFileEquals(Path.Combine(fixtureRoot, "expected", "break-queue.csv"), Path.Combine(outputDirectory, "break-queue.csv"));
        AssertFileEquals(Path.Combine(fixtureRoot, "expected", "end-of-day-report.txt"), Path.Combine(outputDirectory, "end-of-day-report.txt"));
    }

    [Fact]
    public void OverrideAndRerunFixtureRemainsStable()
    {
        var fixtureRoot = GetFixtureRoot("override-rerun");
        var outputDirectory = PrepareOutputDirectory("override-rerun");

        ExecuteBatch(fixtureRoot, outputDirectory);

        var firstMatchedTrades = File.ReadAllText(Path.Combine(outputDirectory, "matched-trades.csv"));
        var firstReport = File.ReadAllText(Path.Combine(outputDirectory, "end-of-day-report.txt"));
        var firstLedger = File.ReadAllText(Path.Combine(outputDirectory, "run-ledger.csv"));

        AssertFileEquals(Path.Combine(fixtureRoot, "expected", "matched-trades.csv"), Path.Combine(outputDirectory, "matched-trades.csv"));
        AssertFileEquals(Path.Combine(fixtureRoot, "expected", "break-queue.csv"), Path.Combine(outputDirectory, "break-queue.csv"));
        AssertFileEquals(Path.Combine(fixtureRoot, "expected", "end-of-day-report.txt"), Path.Combine(outputDirectory, "end-of-day-report.txt"));

        ExecuteBatch(fixtureRoot, outputDirectory);

        Assert.Equal(firstMatchedTrades, File.ReadAllText(Path.Combine(outputDirectory, "matched-trades.csv")));
        Assert.Equal(firstReport, File.ReadAllText(Path.Combine(outputDirectory, "end-of-day-report.txt")));
        Assert.Equal(firstLedger, File.ReadAllText(Path.Combine(outputDirectory, "run-ledger.csv")));
    }

    [Fact]
    public void DuplicateOverridesAreAudited()
    {
        var fixtureRoot = GetFixtureRoot("override-rerun");
        var workingRoot = PrepareOutputDirectory("duplicate-overrides-input");
        var inputDirectory = Path.Combine(workingRoot, "input");
        var outputDirectory = PrepareOutputDirectory("duplicate-overrides-output");

        Directory.CreateDirectory(inputDirectory);
        foreach (var fileName in new[] { "trades.csv", "positions.csv", "settlements.csv", "overrides.csv" })
        {
            File.Copy(Path.Combine(fixtureRoot, "input", fileName), Path.Combine(inputDirectory, fileName));
        }

        File.AppendAllText(Path.Combine(inputDirectory, "overrides.csv"), "T-1003,ForceMatch,Superseded duplicate instruction,ops-manager" + Environment.NewLine);

        ExecuteBatch(workingRoot, outputDirectory);

        var report = File.ReadAllText(Path.Combine(outputDirectory, "end-of-day-report.txt"));
        Assert.Contains("Stale Overrides: 1", report, StringComparison.Ordinal);
        Assert.Contains("T-1003: ForceMatch (ops-manager)", report, StringComparison.Ordinal);
    }

    [Fact]
    public void AdapterUsesShellFreeDotnetCommands()
    {
        var root = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", ".."));
        var adapterPath = Path.Combine(root, "benchmark-adapter.json");
        var adapter = JsonDocument.Parse(File.ReadAllText(adapterPath));
        var rootElement = adapter.RootElement;

        Assert.Equal("dotnet", rootElement.GetProperty("build").GetProperty("executable").GetString());
        Assert.Equal("dotnet", rootElement.GetProperty("test").GetProperty("executable").GetString());
        Assert.Equal("dotnet", rootElement.GetProperty("run").GetProperty("executable").GetString());

        var buildArgs = rootElement.GetProperty("build").GetProperty("arguments").EnumerateArray().Select(node => node.GetString()).ToArray();
        Assert.Contains("build", buildArgs);
        Assert.Contains("LegacyTradeReconciliation.sln", buildArgs);

        var runArgs = rootElement.GetProperty("run").GetProperty("arguments").EnumerateArray().Select(node => node.GetString()).ToArray();
        Assert.Contains("{businessDate}", runArgs);
        Assert.Contains("{inputDirectory}", runArgs);
        Assert.Contains("{outputDirectory}", runArgs);

        Assert.Equal(4, rootElement.GetProperty("outputs").GetArrayLength());
    }

    private static string GetFixtureRoot(string fixtureName)
    {
        return Path.Combine(AppContext.BaseDirectory, "Fixtures", fixtureName);
    }

    private static string PrepareOutputDirectory(string name)
    {
        var directory = Path.Combine(Path.GetTempPath(), "legacy-trade-reconciliation-tests", name + "-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(directory);
        return directory;
    }

    private static void ExecuteBatch(string fixtureRoot, string outputDirectory)
    {
        var exitCode = new ReconciliationBatch().Run(new[]
        {
            "2025-03-17",
            Path.Combine(fixtureRoot, "input"),
            outputDirectory
        });

        Assert.Equal(0, exitCode);
    }

    private static void AssertFileEquals(string expectedPath, string actualPath)
    {
        Assert.Equal(File.ReadAllText(expectedPath), File.ReadAllText(actualPath));
    }
}

